sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({ api, helpers }) {
  let html = `
    <style>
      .main-text {
        font-size: 16px;
        font-weight: 500;
        color: #333;
        line-height: 1.7;
        margin: 0;
        display: flex;
        align-items: center;
        background-color: #FFF3CD; /* Light yellow background */
        padding: 8px 12px;
        border-radius: 4px;
        border-left: 4px solid #FFC107; /* Yellow border on the left */
      }
      .icon {
        color: #856404; /* This won't affect the emoji color but matches the design */
        font-size: 20px;
        margin-right: 8px;
        vertical-align: middle;
      }
    </style>
    <p class="main-text">
      <span class="icon">⚠️</span> Required flow for Automate Non Standard Software Request is not Installed. Please install before proceeding.
    </p>
  `;

  return html;
}
